import{gt as e,nt as t,o as n,rt as r}from"./chunks/framework.CTZrU_RR.js";var i=JSON.parse(`{"title":"Release Smoke Checks","description":"Build a real app against the module — from this repo or from npm — and verify it works, optionally on Cloudflare Pages and Vercel.","frontmatter":{"title":"Release Smoke Checks","description":"Build a real app against the module — from this repo or from npm — and verify it works, optionally on Cloudflare Pages and Vercel.","outline":"deep"},"headers":[],"relativePath":"guide/release-smoke.md","filePath":"guide/release-smoke.md","lastUpdated":1785409018000}`),a={name:`guide/release-smoke.md`};function o(n,i,a,o,s,c){return e(),t(`div`,null,[...i[0]||=[r(`<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /nuxt-i18n-micro/guide/release-smoke.md for this page in Markdown format</div><h1 id="release-smoke-checks" tabindex="-1">Release Smoke Checks <a class="header-anchor" href="#release-smoke-checks" aria-label="Permalink to “Release Smoke Checks”">​</a></h1><p>The unit, integration and e2e suites all run against the module&#39;s source. None of them answer the question that actually matters after a release: <strong>does the published package install into a fresh app and work?</strong></p><p>That is what this workflow does. It builds a small real Nuxt app (<a href="https://github.com/s00d/nuxt-i18n-micro/tree/main/test/deploy-smoke" target="_blank" rel="noreferrer"><code>test/deploy-smoke</code></a>) against the module and asserts on the running result.</p><h2 id="two-sources-two-different-failures" tabindex="-1">Two sources, two different failures <a class="header-anchor" href="#two-sources-two-different-failures" aria-label="Permalink to “Two sources, two different failures”">​</a></h2><table tabindex="0"><thead><tr><th>Source</th><th>What it installs</th><th>What it catches</th></tr></thead><tbody><tr><td><code>git</code></td><td>tarballs packed from the current checkout</td><td>packaging problems <strong>before</strong> you publish: missing files, unresolved <code>workspace:</code>/<code>catalog:</code> protocols, dependencies that were used but never declared</td></tr><tr><td><code>npm</code></td><td><code>nuxt-i18n-micro@latest</code> (or a version you name)</td><td>what users actually get: a bad publish, a package that never reached the registry, a version mismatch between the module and <code>@i18n-micro/*</code></td></tr></tbody></table><p>Both run by default. They fail for different reasons, so neither replaces the other.</p><div class="tip custom-block"><p class="custom-block-title">Why <code>git</code> needs more than one tarball</p><p><code>pnpm pack</code> rewrites <code>workspace:*</code> to the local version numbers — which are exactly the ones not on npm yet. So <a href="https://github.com/s00d/nuxt-i18n-micro/blob/main/scripts/src/commands/smoke-pack.ts" target="_blank" rel="noreferrer"><code>scripts/src/commands/smoke-pack.ts</code></a> packs every workspace package and rewrites each tarball&#39;s <code>@i18n-micro/*</code> dependencies to point at its siblings. Without that the install goes to the registry for a version that does not exist.</p><p>Use <code>pnpm pack</code>, never <code>npm pack</code>: only pnpm substitutes the <code>workspace:</code> and <code>catalog:</code> protocols, and a tarball still containing them cannot be installed at all.</p></div><h2 id="running-it" tabindex="-1">Running it <a class="header-anchor" href="#running-it" aria-label="Permalink to “Running it”">​</a></h2><p><strong>From the GitHub UI</strong>: Actions → <em>release smoke</em> → <em>Run workflow</em>. Choose the source (<code>both</code>, <code>git</code>, <code>npm</code>), optionally a specific npm version, and whether to deploy.</p><p><strong>Automatically</strong>: on every published release, plus once a day — npm needs a few minutes to serve a freshly published version, and the daily run catches a release that was not yet queryable when the publish job finished.</p><p><strong>Locally</strong>, against the current checkout:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># pack this checkout and point the app at it</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> prepack</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -C</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cli</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> smoke-pack</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --app</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test/deploy-smoke</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --out</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/tarballs</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test/deploy-smoke</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">printf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;packages:\\n  - .\\n&#39;</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pnpm-workspace.yaml</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-frozen-lockfile</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nuxt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PORT</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">3000</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .output/server/index.mjs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># back in the repo root</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -C</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cli</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> smoke-verify</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --url</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:3000</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -C</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cli</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> smoke-browser</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --url</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:3000</span></span></code></pre></div><p>To check a published version instead, skip the packing and set the dependency to <code>nuxt-i18n-micro@3.21.4</code> (or <code>latest</code>) before installing.</p><h2 id="what-is-asserted" tabindex="-1">What is asserted <a class="header-anchor" href="#what-is-asserted" aria-label="Permalink to “What is asserted”">​</a></h2><p><a href="https://github.com/s00d/nuxt-i18n-micro/blob/main/scripts/src/commands/smoke-verify.ts" target="_blank" rel="noreferrer"><code>scripts/src/commands/smoke-verify.ts</code></a> takes a base URL, so the same checks run against a local server, a Cloudflare Pages deployment or a Vercel one:</p><ul><li><strong>SSR and localized routes</strong> — <code>/</code>, <code>/de</code>, <code>/fr</code> and <code>/de/about</code> each render their own translations, interpolation and plurals resolve, and no page contains a raw translation key</li><li><strong>Payload route</strong> — <code>/_locales/index/de/data.json</code> returns the right chunk and is not served <code>no-store</code></li><li><strong>SEO</strong> — <code>hreflang</code> for every locale plus <code>x-default</code>, a <code>canonical</code> link, <code>og:locale</code>, and <code>&lt;html lang&gt;</code> matching the locale</li></ul><p><a href="https://github.com/s00d/nuxt-i18n-micro/blob/main/scripts/src/commands/smoke-browser.ts" target="_blank" rel="noreferrer"><code>scripts/src/commands/smoke-browser.ts</code></a> adds what only a browser can see: hydration, client-side navigation between pages and locales, that no raw key is ever visible mid-transition, and that nothing threw.</p><h2 id="deploying-from-ci" tabindex="-1">Deploying from CI <a class="header-anchor" href="#deploying-from-ci" aria-label="Permalink to “Deploying from CI”">​</a></h2><p>Deployment is off unless you tick <em>deploy</em> on a manual run. It always uses the <strong>published</strong> package — the point is to verify what a user would get, and a local tarball would not survive the platform&#39;s own install step.</p><p>Create dedicated projects for this. Do not point it at a project you deploy by hand: every run overwrites the deployment.</p><h3 id="cloudflare-pages" tabindex="-1">Cloudflare Pages <a class="header-anchor" href="#cloudflare-pages" aria-label="Permalink to “Cloudflare Pages”">​</a></h3><p><strong>1. Create the project.</strong> Open <a href="https://dash.cloudflare.com" target="_blank" rel="noreferrer">https://dash.cloudflare.com</a>, pick your account, then <em>Compute (Workers &amp; Pages)</em> → <strong>Create</strong> → the <strong>Pages</strong> tab → <strong>Upload assets</strong>. Give it a name — <code>nuxt-i18n-micro-smoke</code> — and drop in any file as a placeholder; CI replaces the whole thing on its first run. A direct-upload project needs no Git connection, which is what you want here: the deploys come from this workflow, not from a branch.</p><p>The name you typed is the value for <code>CLOUDFLARE_PROJECT_NAME</code>.</p><p><strong>2. Account ID.</strong> Look at the dashboard URL while inside the account:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>https://dash.cloudflare.com/8f1a2b3c4d5e6f7890abcdef12345678/workers-and-pages</span></span>
<span class="line"><span>                            └──────────── this is the account ID ────────────┘</span></span></code></pre></div><p>It is also printed in the right-hand sidebar of the Workers &amp; Pages overview, under <em>Account details</em>. That value is <code>CLOUDFLARE_ACCOUNT_ID</code>.</p><p><strong>3. API token.</strong> Go to <a href="https://dash.cloudflare.com/profile/api-tokens" target="_blank" rel="noreferrer">https://dash.cloudflare.com/profile/api-tokens</a> → <strong>Create Token</strong> → scroll past the templates to <strong>Custom token</strong> → <strong>Get started</strong>.</p><p>Fill it in like this:</p><table tabindex="0"><thead><tr><th>Field</th><th>What to put</th></tr></thead><tbody><tr><td>Token name</td><td><code>nuxt-i18n-micro smoke deploy</code> — free text, only for you</td></tr><tr><td>Permissions</td><td>one row: <strong>Account</strong> · <strong>Cloudflare Pages</strong> · <strong>Edit</strong></td></tr><tr><td>Account Resources</td><td><strong>Include</strong> · the account you used in step 1</td></tr><tr><td>Client IP Address Filtering</td><td>leave empty — GitHub runners have no fixed IP</td></tr><tr><td>TTL</td><td>leave empty, or set an expiry date if you rotate tokens</td></tr></tbody></table><p><strong>Edit</strong> rather than <strong>Read</strong> because the token has to create deployments, not just list them. One permission row is enough — nothing here touches DNS or zones.</p><p>Then <strong>Continue to summary</strong> → <strong>Create Token</strong>. The token appears <strong>once</strong>, on that screen only. Copy it now; if you lose it, delete the token and make a new one. That value is <code>CLOUDFLARE_API_TOKEN</code>.</p><h3 id="vercel" tabindex="-1">Vercel <a class="header-anchor" href="#vercel" aria-label="Permalink to “Vercel”">​</a></h3><p><strong>1. Create and link the project.</strong> In <code>test/deploy-smoke</code>, run:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dlx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vercel</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> link</span></span></code></pre></div><p>It asks four things: which scope (your personal account, or a team if you have one), whether to link to an existing project (answer <strong>no</strong>), the project name (<code>nuxt-i18n-micro-smoke</code>), and the directory (press enter for <code>./</code>). This creates the project on Vercel and writes <code>test/deploy-smoke/.vercel/project.json</code>:</p><div class="language-json"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;orgId&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;team_xxxxxxxxxxxxxxxxxxxx&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;projectId&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;prj_xxxxxxxxxxxxxxxxxxxx&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><p>Newer CLI versions also write a <code>projectName</code>; ignore it, nothing reads it. Only <code>orgId</code> and <code>projectId</code> matter — they become <code>VERCEL_ORG_ID</code> and <code>VERCEL_PROJECT_ID</code>. <code>orgId</code> starts with <code>team_</code> for a team and is a plain user id for a personal account; copy either verbatim. The same pair is in the dashboard under <em>Project Settings → General</em>.</p><p><strong>Do not commit <code>.vercel/</code>.</strong> It is in <code>.gitignore</code> already. CI never reads the file: with <code>VERCEL_ORG_ID</code> and <code>VERCEL_PROJECT_ID</code> in the environment, <code>vercel pull</code> recreates it on the runner. Locally the directory is only there to keep your own CLI linked — deleting it unlinks the directory and nothing else.</p><p><strong>2. Token.</strong> Open <a href="https://vercel.com/account/tokens" target="_blank" rel="noreferrer">https://vercel.com/account/tokens</a> → <strong>Create Token</strong>.</p><table tabindex="0"><thead><tr><th>Field</th><th>What to put</th></tr></thead><tbody><tr><td>Token Name</td><td><code>nuxt-i18n-micro smoke deploy</code></td></tr><tr><td>Scope</td><td>the account or team that owns the project — this is where the ambiguity is: a personal token cannot deploy a team project, and vice versa. Pick the one whose name matches the scope you chose during <code>vercel link</code></td></tr><tr><td>Expiration</td><td>your call; the workflow keeps working until it expires, then fails with a 403</td></tr></tbody></table><p>Click <strong>Create</strong>. The value is shown <strong>once</strong> — that is <code>VERCEL_TOKEN</code>.</p><p>Prefer the CLI? <code>pnpm dlx vercel tokens add &quot;nuxt-i18n-micro smoke deploy&quot;</code> prints the token to stdout. Add <code>--project prj_xxxxxxxxxxxxxxxxxxxx</code> to restrict it to this one project, so a leak cannot touch anything else. Note that minting a token this way needs an existing account-scoped token — a fresh <code>vercel login</code> session cannot do it, so the first token has to come from the dashboard.</p><h3 id="after-deploying" tabindex="-1">After deploying <a class="header-anchor" href="#after-deploying" aria-label="Permalink to “After deploying”">​</a></h3><p>CI waits for the new deployment to answer, then runs the same HTTP and browser checks against the live URL. A green deploy job means the published package works on that platform&#39;s runtime — not just in a local Node server.</p>`,45)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};